programa {
 funcao inicio() {
 inteiro n = 7
 real r = 2.5
 cadeia nome = "Ana"
 logico ativo = verdadeiro
 se (ativo) { escreva(nome, ":", n, ":", r) }
 }
}

programa {
 funcao inicio() {
 inteiro n
 leia(n)
 escreva(n + 1)
 }
}

programa {
 funcao inicio() {
 real salario = 2000.0
 real novo = salario * 1.10
 se (novo > 2199.99 e novo < 2200.01) { escreva("OK") }
 }
}

programa {
 funcao inicio() {
 inteiro a = 8
 se (a >= 5 e a != 9) { escreva("sim") } senao { escreva("nao") }
 }
}

programa {
 funcao inicio() {
 inteiro n = 12
 se (n < 10) { escreva("A") } senao se (n < 20) { escreva("B") } senao { escreva("C") }
 }
}

programa {
 funcao inicio() {
 inteiro n = 2
 escolha (n) { caso 1: escreva("A") pare caso 2: escreva("B") pare caso contrario: escreva("C") }
 }
}

programa {
 funcao inicio() {
 inteiro soma = 0
 para (inteiro i = 1; i <= 5; i++) { soma = soma + i }
 escreva(soma)
 }
}

programa {
 funcao inicio() {
 escreva(dobro(21))
 }
 funcao inteiro dobro(inteiro n) { retorne n * 2 }
}
